class Solution {
public:
    vector<vector<int>> candyCrush(vector<vector<int>>& board) {
        int rows = board.size();
        int cols = board[0].size();
        while (true) {
            vector<vector<bool>> crush(rows, vector<bool>(cols, false));
            bool found = false;
            for (int r = 0; r < rows; ++r) {
                for (int c = 0; c + 2 < cols; ++c) {
                    int v = board[r][c];
                    if (v != 0 && v == board[r][c + 1]
                        && v == board[r][c + 2]) {
                        crush[r][c] = crush[r][c + 1] = crush[r][c + 2] = true;
                        found = true;
                    }
                }
            }
            for (int c = 0; c < cols; ++c) {
                for (int r = 0; r + 2 < rows; ++r) {
                    int v = board[r][c];
                    if (v != 0 && v == board[r + 1][c]
                        && v == board[r + 2][c]) {
                        crush[r][c] = crush[r + 1][c] = crush[r + 2][c] = true;
                        found = true;
                    }
                }
            }
            if (!found) {
                return board;
            }
            for (int c = 0; c < cols; ++c) {
                int write = rows - 1;
                for (int r = rows - 1; r >= 0; --r) {
                    if (!crush[r][c] && board[r][c] != 0) {
                        board[write--][c] = board[r][c];
                    }
                }
                while (write >= 0) {
                    board[write--][c] = 0;
                }
            }
        }
    }
};
